return items
  .map((item, index) => ({
    json: {
      id: item.json.id,
      keyword: item.json.keyword,
      city: item.json.city || '',
      area: item.json.area || '',
      niche: item.json.niche || '',
      processed: String(item.json.processed || '').toLowerCase(),
      row_number: item.json.row_number || index + 2
    }
  }))
  .filter(item =>
    item.json.keyword &&
    item.json.processed !== 'yes'
  );

const staticData = $getWorkflowStaticData('global');

const item = $input.first().json;

staticData.currentKeyword = item.keyword;
staticData.currentKeywordId = item.id;
staticData.currentKeywordRowNumber = item.row_number;

staticData.currentCity = item.city;
staticData.currentArea = item.area;
staticData.currentNiche = item.niche;

return [
  {
    json: item
  }
];

const staticData = $getWorkflowStaticData('global');

const item = $input.first().json;

const results = item.local_results || [];

return results.map(result => ({
  json: {
    ...result,

    keyword_row_number:
      staticData.currentKeywordRowNumber,

    keyword:
      staticData.currentKeyword,

    keyword_id:
      staticData.currentKeywordId,

    city:
      staticData.currentCity,

    area:
      staticData.currentArea,

    niche:
      staticData.currentNiche
  }
}));

return items.filter(item => {
  const b = item.json;
  return (
    b.reviews > 50 &&
    b.website &&
    b.rating >= 3.5 &&
    b.rating <= 4.7
  );
});

const seen = new Set();
return items.filter(item => {
  const url = item.json.website;
  if (!url || seen.has(url)) return false;
  seen.add(url);
  return true;
});

