const originalData = $json.original_business || $json;

const business = {
  name:
    originalData.title ||
    originalData.name ||
    originalData.business_name ||
    'Unknown',
  website: originalData.website || '',
  rating: Number(originalData.rating || 0),
  reviews: Number(originalData.reviews || 0),
  phone: originalData.phone || '',
  address: originalData.address || '',
  keyword_row_number: originalData.keyword_row_number || null,
  place_id: originalData.place_id || originalData.data_id || '',
  category: originalData.type || originalData.category || '',
  keyword: originalData.keyword || '',
  city: originalData.city || '',
  area: originalData.area || '',
  niche: originalData.niche || ''
};

let analysis = {};

try {
  let rawContent =
    $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

  // Strip markdown fences (safety net even with responseMimeType set)
  rawContent = rawContent
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  // Extract the JSON object in case there's any leading/trailing text
  const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON object found in response');

  analysis = JSON.parse(jsonMatch[0]);

} catch (e) {
  analysis = {
    business_name: business.name,
    automation_score: 0,
    urgency_score: 0,
    issues: [],
    outreach_angle: 'Unable to analyze — parsing failed',
    ai_opportunity_summary: '',
    best_offer_to_pitch: '',
    likely_decision_maker: ''
  };
}

const issues = analysis.issues || [];
const issueCount = issues.length;

const highSeverityCount = issues.filter(
  i => (i.severity || '').toLowerCase() === 'high'
).length;

const avgConfidence =
  issueCount > 0
    ? issues.reduce(
        (sum, i) => sum + (i.confidence_score || i.confidence || 0),
        0
      ) / issueCount
    : 0;

// --- Scoring ---
const reviewScore   = Math.min(30, (business.reviews || 0) / 10);
const ratingScore   = Math.max(0, Math.min(40, ((business.rating || 0) - 3.5) * 20));
const websiteScore  =
  business.website &&
  !business.website.includes('instagram.com') &&
  !business.website.includes('facebook.com')
    ? 20 : 0;

const businessQualityScore = reviewScore + ratingScore + websiteScore;

const issueScore      = Math.min(40, issueCount * 8);
const severityScore   = Math.min(30, highSeverityCount * 10);
const confidenceScore = Math.min(30, avgConfidence * 0.3);
const automationNeedScore = issueScore + severityScore + confidenceScore;

const leadScore = Math.round(
  (businessQualityScore * 0.4) + (automationNeedScore * 0.6)
);

// --- Output ---
return {
  json: {
    place_id: business.place_id,
    business_name: analysis.business_name || business.name,
    website: business.website,
    google_maps_link: business.place_id
      ? `https://www.google.com/maps/place/?q=place_id:${business.place_id}`
      : '',
    rating: business.rating,
    reviews: business.reviews,
    phone: business.phone,
    address: business.address,
    category: business.category,
    keyword: business.keyword,
    niche: business.niche,
    city: business.city,
    area: business.area,
    automation_score: analysis.automation_score || leadScore,
    urgency_score: analysis.urgency_score || 0,
    lead_score: leadScore,
    automation_opportunities: JSON.stringify(
      issues.slice(0, 3).map(i => ({
        issue: i.issue,
        solution: i.suggested_solution
      }))
    ),
    ai_summary: analysis.ai_opportunity_summary || '',
    best_offer: analysis.best_offer_to_pitch || '',
    decision_maker: analysis.likely_decision_maker || '',
    pain_points: issues.map(i => i.issue).join(', '),
    recommended_solution: issues[0]?.suggested_solution || '',
    outreach_angle: analysis.outreach_angle || '',
    issues_count: issueCount,
    high_severity_issues: highSeverityCount,
    keyword_row_number: business.keyword_row_number,
    contacted: 'no',
    status: 'new',
    analyzed_at: new Date().toISOString()
  }
};

const staticData = $getWorkflowStaticData('global');

staticData.currentKeywordId = $json.id;
staticData.currentKeyword = $json.keyword;
staticData.currentKeywordRowNumber = $json.row_number;

return items;

return items.map(item => {
  const website = (item.json.website || '').toLowerCase();

  const hasRealWebsite =
    website &&
    !website.includes('instagram.com') &&
    !website.includes('facebook.com') &&
    !website.includes('zomato') &&
    !website.includes('swiggy') &&
    !website.includes('linkedin.com') &&
    !website.includes('twitter.com') &&
    !website.includes('x.com');

  item.json.has_real_website = hasRealWebsite;

  return item;
});

const businessData = {
  place_id: $json.place_id || '',
  name: $json.title || 'Unknown Business',
  rating: $json.rating || null,
  reviews: $json.reviews || 0,
  phone: $json.phone || '',
  address: $json.address || '',
  website: $json.website || '',
  category: $json.type || '',
  keyword: $json.keyword || '',
  keyword_row_number: $json.keyword_row_number || null,
  has_real_website: $json.has_real_website || false
};


let websiteContent = ($json.data && $json.data.markdown)
  ? $json.data.markdown
  : '';

websiteContent = websiteContent
  .replace(/!\[.*?\]\(.*?\)/g, '')
  .replace(/\[([^\]]*)\]\([^\)]*\)/g, '$1')
  .replace(/[\\*_`#>]/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .substring(0, 1500);

const hasWebsiteContent =
  websiteContent &&
  websiteContent !== 'No website content available';

const systemPrompt = `
You are an elite SMB automation consultant and AI systems strategist.

Your task is to analyze businesses and identify:
- operational inefficiencies
- customer service bottlenecks
- manual workflows
- poor digital presence
- weak customer engagement systems
- missing automations
- AI assistant opportunities
- CRM opportunities
- lead capture issues
- booking/order inefficiencies
- missing analytics systems
- reputation management gaps
- marketing automation opportunities

You must think like:
- an automation agency
- an AI consultant
- a SaaS founder
- a cold outreach strategist

If the business has NO real website:
focus heavily on:
- weak digital presence
- poor discoverability
- Instagram-only presence
- missing booking systems
- lack of lead capture
- lack of automation
- lack of SEO
- reputation management opportunities

For every issue provide:
- issue
- severity
- suggested_solution
- business_impact
- confidence_score
- estimated_monthly_value

Also generate:
- automation_score (0-100)
- urgency_score (0-100)
- outreach_angle
- best_offer_to_pitch
- likely_decision_maker
- ai_opportunity_summary

Return ONLY valid JSON.

JSON format:
{
  "business_name": "string",
  "automation_score": 0,
  "urgency_score": 0,
  "website_quality": "string",
  "digital_presence": "string",
  "best_offer_to_pitch": "string",
  "likely_decision_maker": "string",
  "ai_opportunity_summary": "string",
  "issues": [
    {
      "issue": "string",
      "severity": "High",
      "suggested_solution": "string",
      "business_impact": "string",
      "confidence_score": 90,
      // "estimated_monthly_value": "string"
    }
  ],
  "outreach_angle": "string"
}
`;

const userContent = `
Business Name: ${businessData.name}
Category: ${businessData.category}
Rating: ${businessData.rating}/5
Reviews: ${businessData.reviews}
Address: ${businessData.address}
Phone: ${businessData.phone}
Website: ${businessData.website}
Keyword: ${businessData.keyword}

Has Real Website: ${businessData.has_real_website}

Website Content:
${hasWebsiteContent ? websiteContent : 'NO WEBSITE CONTENT AVAILABLE'}

Analyze this business thoroughly.
`;

return {
  json: {
    original_business: $json,

    request_body: {
      contents: [
        {
          parts: [
            {
              text: `
${systemPrompt}

${userContent}

IMPORTANT:
Return ONLY valid JSON.
Do not wrap JSON in markdown.
Do not add explanations.
`
            }
          ]
        }
      ],

      generationConfig: {
        temperature: 0.3,
        maxOutputTokens: 4000,
        responseMimeType: "application/json",   // also add this (fixes markdown fence issue)
        thinkingConfig: {
          thinkingBudget: 0                     // disables thinking entirely
        }
      }
    }
  }
};
